begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('event-stage2-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','event-stage2-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','event-stage2-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;
set local role authenticated;
select pg_temp.actor('owner');
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('account'),'kind','account','name','Banco fictício'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('income'),'kind','category','name','Receita fictícia','direction','income'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('expense'),'kind','category','name','Taxa fictícia','direction','expense'));
select public.finance_digital(pg_temp.fi('org'),pg_temp.fi('a'),'purpose',jsonb_build_object('id',pg_temp.fi('purpose'),'version',0,'name','Oferta fictícia','origin','event','account',pg_temp.fi('account'),'category',pg_temp.fi('income'),'feeCategory',pg_temp.fi('expense'),'refundCategory',pg_temp.fi('expense'),'creditCategory',pg_temp.fi('income'),'active',true));
reset role;
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured) values(pg_temp.fi('receiver'),pg_temp.fi('org'),pg_temp.fi('a'),'mercado_pago','production','configured','123','Conta fictícia',true,array[pg_temp.fi('a')],pg_temp.fi('account'),pg_temp.fi('owner'),now()+interval '1 day',array['pix'],true,true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.member_payment_publish(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('purpose'),pg_temp.fi('receiver'),true)$$,'publica finalidade com destino válido');

reset role;
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity,status) values(pg_temp.fi('event2'),pg_temp.fi('org'),pg_temp.fi('a'),'Tickets fictícios etapa 2','event',now()+interval '2 days',now()+interval '3 days',10,'published');
create function pg_temp.v() returns integer language sql security definer set search_path='' as $$select version from private.church_app_events where id=pg_temp.fi('event2')$$;
create function pg_temp.admin2(a text,i uuid default null,d jsonb default '{}') returns jsonb language sql as $$select public.event_ticket_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),a,i,pg_temp.v(),d)$$;
create function pg_temp.settings2() returns jsonb language sql as $$select jsonb_build_object('enabled',true,'allow_guests',true,'show_remaining',true,'purpose',pg_temp.fi('purpose'),'receiving_unit',pg_temp.fi('a'),'reservation_hours',24,'questions','[]'::jsonb)$$;
create function pg_temp.type2(n text,mode text,price integer,quantity integer) returns jsonb language sql as $$select jsonb_build_object('name',n,'mode',mode,'price',price::text,'quantity',quantity::text,'starts',now()-interval '1 day','ends',now()+interval '1 day','active',true,'per_user','2','per_cpf','','audience','public','audience_units','[]'::jsonb,'position',0)$$;
create function pg_temp.payload2(t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select jsonb_build_object('buyerName','Pessoa fictícia','buyerEmail',buyer||'-family@example.invalid','emailConfirmation',buyer||'-family@example.invalid','coupon','','intent',intent,'items',jsonb_build_array(jsonb_build_object('type',pg_temp.fi(t),'name','Participante fictício','email','','cpf','','phone','','answers','{}'::jsonb)))$$;
create function pg_temp.buy2(id text,t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi(id),case when buyer='guest' then null else pg_temp.fi(buyer) end,repeat('a',64),pg_temp.payload2(t,buyer,intent),repeat('f',64))$$;
set local role authenticated;select pg_temp.actor('member');
select throws_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2())$$,'42501','event_ticket_denied','membro não configura tickets');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2())$$,'admin configura recebimento e inscrições de visitantes');
select lives_ok($$select pg_temp.admin2('type',pg_temp.fi('free'),pg_temp.type2('Gratuito fictício','free',0,2))$$,'cria tipo gratuito com estoque');
select lives_ok($$select pg_temp.admin2('type',pg_temp.fi('paid'),pg_temp.type2('Pago fictício','paid',1500,4))$$,'cria tipo pago');
select lives_ok($$select pg_temp.admin2('type',pg_temp.fi('reserve'),pg_temp.type2('Reserva fictícia','reservation',2500,4))$$,'cria reserva com opção de pagamento');
select is(jsonb_array_length(public.member_event_ticket_catalog(pg_temp.fi('event2'))->'types'),3,'catálogo mostra os três tipos');
select ok(not has_function_privilege('authenticated','public.event_ticket_checkout(uuid,text,uuid,uuid,text,jsonb,text)','execute'),'cliente não invoca processamento privilegiado');
select ok(not has_table_privilege('anon','private.event_ticket_orders','select'),'visitante não lê pedidos diretamente');
reset role;
select lives_ok($$select pg_temp.buy2('free-order','free')$$,'confirma gratuito');
select lives_ok($$select pg_temp.buy2('free-order','free')$$,'repetir pedido não duplica vaga');
select is((select count(*)::integer from private.event_ticket_items where order_id=pg_temp.fi('free-order')),1,'um participante e um ticket');
select is((select state from private.event_ticket_orders where id=pg_temp.fi('free-order')),'confirmed','gratuito confirmado sem financeiro');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'status',pg_temp.fi('free-order'),pg_temp.fi('member'),repeat('b',64))$$,'titular autenticado consulta pedido em outro dispositivo');
select throws_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'status',pg_temp.fi('free-order'),pg_temp.fi('second'),repeat('a',64))$$,'42501','event_ticket_proof','outra conta não acessa o pedido');
select lives_ok($$select pg_temp.buy2('free-guest','free','guest')$$,'visitante inscrito sem criar conta de membro');
select throws_ok($$select pg_temp.buy2('free-full','free','second')$$,'40001','event_ticket_full','estoque esgotado impede outra inscrição');
select lives_ok($$select pg_temp.buy2('reserve-order','reserve','member','reserve')$$,'reserva mantém vaga sem gerar cobrança');
select is((select finance_order from private.event_ticket_orders where id=pg_temp.fi('reserve-order')),null::uuid,'reserva não gera pagamento automaticamente');
select is(public.event_ticket_checkout(pg_temp.fi('event2'),'status',pg_temp.fi('reserve-order'),pg_temp.fi('member'),repeat('a',64))->'items'->0->>'code',null,'reserva não paga não libera entrada');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'pay',pg_temp.fi('reserve-order'),pg_temp.fi('member'),repeat('a',64))$$,'converte reserva em pagamento no mesmo pedido');
select is((select count(*)::integer from private.finance_digital_orders where id=pg_temp.fi('reserve-order')),1,'um pedido financeiro para a reserva');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'pay',pg_temp.fi('reserve-order'),pg_temp.fi('member'),repeat('a',64))$$,'retomar pagamento reutiliza pedido');
select lives_ok($$select pg_temp.buy2('paid-order','paid','second')$$,'pago aguarda confirmação do provedor');
select is((select state from private.event_ticket_orders where id=pg_temp.fi('paid-order')),'holding','criar checkout não é confirmar pagamento');
select is((select (classification->>'name') from private.finance_digital_orders where id=pg_temp.fi('paid-order')),'Oferta fictícia','classificação financeira foi copiada');
select is((select gross::integer from private.finance_digital_orders where id=pg_temp.fi('paid-order')),1500,'valor vem do tipo cadastrado, em centavos');
select throws_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi('paid-order'),pg_temp.fi('second'),repeat('a',64),jsonb_set(pg_temp.payload2('paid','second'),'{buyerName}','"Outro comprador"'),repeat('f',64))$$,'40001','event_ticket_changed','mesma tentativa não aceita outro conteúdo');
select is(public.event_ticket_checkout(null,'mine',null,pg_temp.fi('member'))->'items'->0->>'buyerEmail','member-family@example.invalid','titular consulta somente seu histórico');

update private.event_ticket_types set per_user=1 where id=pg_temp.fi('paid');
update auth.users set email='changed-second@example.invalid' where id=pg_temp.fi('second');
select throws_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi('changed-email-order'),pg_temp.fi('second'),repeat('a',64),pg_temp.payload2('paid','second')||'{"buyerEmail":"changed-second@example.invalid","emailConfirmation":"changed-second@example.invalid"}'::jsonb,repeat('f',64))$$,'22023','event_ticket_person_limit','alterar e-mail não reinicia limite da conta');
update auth.users set email='second-family@example.invalid' where id=pg_temp.fi('second');

-- Local rollback-only tests; no external provider calls.
select throws_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'status',pg_temp.fi('free-guest'),null,repeat('b',64))$$,'42501','event_ticket_proof','visitante exige comprovante privado correto');
select throws_ok($$select pg_temp.buy2('unconfirmed-order','reserve','unconfirmed','reserve')$$,'42501','event_ticket_login','conta sem e-mail confirmado não compra');
select is(public.event_ticket_checkout(pg_temp.fi('event2'),'quote',pg_temp.fi('quote'),pg_temp.fi('second'),repeat('a',64),pg_temp.payload2('reserve','second','reserve'),repeat('f',64))->>'total','2500','conferência calcula total sem criar pedido');
select is((select count(*)::integer from private.event_ticket_orders where id=pg_temp.fi('quote')),0,'conferência não ocupa vagas');
select throws_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi('stale'),pg_temp.fi('second'),repeat('a',64),pg_temp.payload2('reserve','second','reserve')||'{"expectedTotal":"1","revision":1}'::jsonb,repeat('f',64))$$,'40001','event_ticket_quote_changed','preço alterado exige nova conferência');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin2('coupon',pg_temp.fi('coupon'),jsonb_build_object('code','VINHA50','kind','percent','value','50','ends',now()+interval '1 day','limit','1','once',true,'types',jsonb_build_array(pg_temp.fi('reserve')),'active',true))$$,'cupom percentual limitado ao tipo de reserva');
reset role;
select is(public.event_ticket_checkout(pg_temp.fi('event2'),'quote',pg_temp.fi('quote2'),pg_temp.fi('second'),repeat('a',64),pg_temp.payload2('reserve','second','reserve')||'{"coupon":"VINHA50"}'::jsonb,repeat('f',64))->>'total','1250','cupom reduz apenas valor elegível');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi('coupon-order'),pg_temp.fi('second'),repeat('a',64),pg_temp.payload2('reserve','second','reserve')||'{"coupon":"VINHA50"}'::jsonb,repeat('f',64))$$,'pedido reserva cupom sem cobrar');
select throws_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'quote',pg_temp.fi('quote3'),pg_temp.fi('owner'),repeat('a',64),pg_temp.payload2('reserve','owner','reserve')||'{"coupon":"VINHA50"}'::jsonb,repeat('f',64))$$,'22023','event_ticket_coupon','limite global de cupom inclui reservas válidas');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'cancel',pg_temp.fi('coupon-order'),pg_temp.fi('second'),repeat('a',64))$$,'cancelar reserva sem cobrança libera vaga e cupom');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'quote',pg_temp.fi('quote3'),pg_temp.fi('owner'),repeat('a',64),pg_temp.payload2('reserve','owner','reserve')||'{"coupon":"VINHA50"}'::jsonb,repeat('f',64))$$,'cupom liberado após cancelamento');
select ok(private.event_cpf_valid('529.982.247-25'),'validação dos dígitos do CPF');
select ok(not private.event_cpf_valid('111.111.111-11'),'CPF repetido é recusado');
select ok(not private.event_ticket_answers_valid('{}','[{"id":"aa000000-0000-4000-8000-000000000001","label":"Idade","kind":"number","required":true,"options":[]}]'),'resposta obrigatória não pode faltar');
select ok(not private.event_ticket_answers_valid('{"extra":"injetado"}','[]'),'respostas extras são recusadas');
select is(public.event_ticket_delivery(pg_temp.fi('paid-order'),'claim')->>'state','dispatching','primeira tentativa de checkout é exclusiva');
select is(public.event_ticket_delivery(pg_temp.fi('paid-order'),'claim')->>'state','in_progress','segunda tentativa não autoriza outro envio');
select lives_ok($$select public.event_ticket_delivery(pg_temp.fi('paid-order'),'uncertain')$$,'falha ambígua preservada para conferência');
select is(public.event_ticket_delivery(pg_temp.fi('paid-order'),'claim')->>'state','uncertain','falha ambígua nunca autoriza nova cobrança');
create function pg_temp.proof2(ord text,state text default 'approved',refunded text default '0') returns jsonb language sql as $$select jsonb_build_object('reference',pg_temp.fi(ord),'externalId',case when ord='paid-order' then '871' else '872' end,'receiverExternalId','123','environment','production','currency','BRL','gross',case when ord='paid-order' then '1500' else '2500' end,'net',case when ord='paid-order' then '1500' else '2500' end,'refunded',refunded,'fees','[]'::jsonb,'state',state,'settlement','available','occurredAt',clock_timestamp(),'paidDate',current_date,'method','pix','installments',1)$$;
select lives_ok($$select private.finance_digital_ingest(pg_temp.fi('receiver'),pg_temp.proof2('paid-order'))$$,'somente prova verificada confirma pagamento');
select is((select state from private.event_ticket_orders where id=pg_temp.fi('paid-order')),'confirmed','aprovação financeira libera ticket');
select ok(public.event_ticket_checkout(pg_temp.fi('event2'),'status',pg_temp.fi('paid-order'),pg_temp.fi('second'),repeat('a',64))->'items'->0->>'code' is not null,'QR individual liberado após aprovação');
select lives_ok($$select private.finance_digital_ingest(pg_temp.fi('receiver'),pg_temp.proof2('paid-order'))$$,'notificação repetida é idempotente');
select lives_ok($$select private.finance_digital_ingest(pg_temp.fi('receiver'),pg_temp.proof2('paid-order','refunded','1500'))$$,'reembolso suspende entrada sem apagar histórico');
select is((select state from private.event_ticket_orders where id=pg_temp.fi('paid-order')),'cancelled','reembolsado não conserva ingresso válido');
select is(public.event_ticket_checkout(pg_temp.fi('event2'),'status',pg_temp.fi('paid-order'),pg_temp.fi('second'),repeat('a',64))->'items'->0->>'code',null,'QR não é exibido depois do reembolso');
update private.event_ticket_orders set expires_at=clock_timestamp()-interval '1 minute' where id=pg_temp.fi('reserve-order');
update private.event_ticket_types set quantity=1 where id=pg_temp.fi('reserve');
select lives_ok($$select pg_temp.buy2('last-reserve','reserve','second','reserve')$$,'vaga expirada pode ser reservada por outro comprador');
select lives_ok($$select private.finance_digital_ingest(pg_temp.fi('receiver'),pg_temp.proof2('reserve-order'))$$,'pagamento tardio é preservado sem exceder estoque');
select is((select state from private.event_ticket_orders where id=pg_temp.fi('reserve-order')),'payment_review','pagamento tardio sem vaga exige conferência');
set local role authenticated;select pg_temp.actor('member');
select throws_ok($$select pg_temp.admin2('registrations')$$,'42501','event_ticket_denied','membro não lista dados de participantes');
select is(jsonb_array_length(public.member_event_ticket_orders(pg_temp.fi('org'))->'items'),2,'histórico autenticado é privado');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin2('registrations')$$,'gestor consulta inscrições');
select throws_ok($$select pg_temp.admin2('checkin',null,jsonb_build_object('code',(select code from private.event_ticket_items where order_id=pg_temp.fi('free-order'))))$$,'42501',null,'tabelas privadas não ficam abertas ao gestor');
reset role;
update private.church_app_events set starts_at=clock_timestamp()+interval '1 hour',ends_at=clock_timestamp()+interval '2 hours' where id=pg_temp.fi('event2');
select set_config('stage2.code',(select code::text from private.event_ticket_items where order_id=pg_temp.fi('free-order')),true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin2('checkin',null,jsonb_build_object('code',current_setting('stage2.code')))$$,'gestor confirma entrada no horário');
select is(pg_temp.admin2('checkin',null,jsonb_build_object('code',current_setting('stage2.code')))->>'already','true','entrada repetida não duplica presença');



-- Stage 3 uses only synthetic fixtures from the rollback transaction above.
reset role;
create function pg_temp.ops(a text,i uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.event_operations_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),a,i,v,d)$$;
set local role authenticated;select pg_temp.actor('member');
select lives_ok($$select public.member_event_interest(pg_temp.fi('event2'),true,true)$$,'conta registra interesse com preferência de e-mail');
select is(public.member_event_interest(pg_temp.fi('event2'))->>'active','true','preferência pertence à conta autenticada');
select throws_ok($$select pg_temp.ops('interests')$$,'42501','event_operations_denied','membro não consulta outros interessados');
select throws_ok($$select pg_temp.ops('finance')$$,'42501','event_operations_denied','membro não consulta financeiro');
select pg_temp.actor('owner');
select is(jsonb_array_length(pg_temp.ops('interests')->'items'),1,'gestor consulta interessados do evento');
select lives_ok($$select pg_temp.ops('message_save',pg_temp.fi('message'),null,jsonb_build_object('title','Aviso fictício','body','Orientação fictícia do evento','audience','interested','email',true,'scheduled',now()+interval '1 minute'))$$,'aviso nasce em rascunho');
select pg_temp.actor('member');
select is((select count(*)::integer from jsonb_array_elements(public.member_agenda_self(pg_temp.fi('org'),'inbox',pg_temp.fi('a'))->'items') item where item->>'message_key'='event-message:'||pg_temp.fi('message')),0,'rascunho não aparece na caixa de entrada');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.ops('message_schedule',pg_temp.fi('message'),1)$$,'gestor confirma a programação');
select throws_ok($$select pg_temp.ops('message_schedule',pg_temp.fi('message'),1)$$,'40001','event_operations_changed','repetição com revisão antiga é recusada');
reset role;
update private.event_messages set scheduled_at=clock_timestamp()-interval '1 minute' where id=pg_temp.fi('message');
set local role authenticated;select pg_temp.actor('member');
select is((select count(*)::integer from jsonb_array_elements(public.member_agenda_self(pg_temp.fi('org'),'inbox',pg_temp.fi('a'))->'items') item where item->>'message_key'='event-message:'||pg_temp.fi('message')),1,'aviso programado chega somente ao público devido');
select pg_temp.actor('second');
select is((select count(*)::integer from jsonb_array_elements(public.member_agenda_self(pg_temp.fi('org'),'inbox',pg_temp.fi('a'))->'items') item where item->>'message_key'='event-message:'||pg_temp.fi('message')),0,'não interessado não recebe aviso segmentado');
reset role;
select ok(not has_function_privilege('authenticated','public.event_email_work(text,uuid,uuid,jsonb)','execute'),'cliente não acessa fila privilegiada');
select ok(not has_table_privilege('authenticated','private.event_refund_cases','select'),'acompanhamento financeiro permanece privado');
select is(jsonb_array_length(public.event_email_work('claim',pg_temp.fi('org'),pg_temp.fi('event2'))->'items'),1,'fila inclui somente interessado que autorizou e-mail');
select is(jsonb_array_length(public.event_email_work('claim',pg_temp.fi('org'),pg_temp.fi('event2'))->'items'),0,'repetição não dispara o mesmo e-mail');
select set_config('event3.job',(select id::text from private.event_email_deliveries where message_id=pg_temp.fi('message')),true);
select set_config('event3.token',(select claim_token::text from private.event_email_deliveries where id=current_setting('event3.job')::uuid),true);
select lives_ok($$select public.event_email_work('settle',null,null,jsonb_build_object('id',current_setting('event3.job'),'token',current_setting('event3.token'),'provider',null))$$,'resposta ambígua fica em conferência');
select is((select state from private.event_email_deliveries where id=current_setting('event3.job')::uuid),'uncertain','e-mail incerto não é reenviado automaticamente');
select lives_ok($$select public.event_email_unsubscribe((select unsubscribe_token from private.event_email_deliveries where id=current_setting('event3.job')::uuid))$$,'descadastro registra bloqueio de e-mails no ministério');
select is((select count(*)::integer from private.event_email_suppressions where organization_id=pg_temp.fi('org')),1,'descadastro não modifica ticket ou conta');
select throws_ok($$select public.event_order_support(pg_temp.fi('event2'),pg_temp.fi('reserve-order'),null,null,'read')$$,'42501','event_support_denied','comprovante ausente não acessa pedido de conta');
select throws_ok($$select public.event_order_support(pg_temp.fi('event2'),pg_temp.fi('reserve-order'),pg_temp.fi('second'),repeat('a',64),'read')$$,'42501','event_support_denied','outra conta não consulta solicitação alheia');
select lives_ok($$select public.event_order_support(pg_temp.fi('event2'),pg_temp.fi('reserve-order'),pg_temp.fi('member'),repeat('a',64),'request',jsonb_build_object('id',pg_temp.fi('refund'),'reason','Motivo fictício de cancelamento','amount','2500'))$$,'titular solicita análise de devolução');
select is((select state from private.event_refund_cases where id=pg_temp.fi('refund')),'requested','solicitar não devolve dinheiro');
select is((select snapshot->>'refunded' from private.finance_digital_receipts where order_id=pg_temp.fi('reserve-order')),'0','solicitação não fabrica prova financeira');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select pg_temp.ops('finance')$$,'financeiro retorna somente contas autorizadas');
select lives_ok($$select pg_temp.ops('refund_review',pg_temp.fi('refund'),1,'{"approve":true,"note":"Aprovado para providência fictícia"}')$$,'financeiro aprova análise com justificativa');
select lives_ok($$select pg_temp.ops('refund_recorded',pg_temp.fi('refund'),2,'{"reference":"Protocolo fictício do provedor"}')$$,'referência externa aguarda comprovação');
reset role;
select is((select state from private.event_refund_cases where id=pg_temp.fi('refund')),'awaiting_provider','registro manual não conclui reembolso');
select lives_ok($$select private.finance_digital_ingest(pg_temp.fi('receiver'),pg_temp.proof2('reserve-order','refunded','2500'))$$,'prova de devolução recebida na integração financeira');
select is((select state from private.event_refund_cases where id=pg_temp.fi('refund')),'completed','somente prova financeira conclui o acompanhamento');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select pg_temp.ops('message_cancel',pg_temp.fi('message'),2)$$,'cancelar aviso impede novas entregas');
select pg_temp.actor('member');
select is((select count(*)::integer from jsonb_array_elements(public.member_agenda_self(pg_temp.fi('org'),'inbox',pg_temp.fi('a'))->'items') item where item->>'message_key'='event-message:'||pg_temp.fi('message')),0,'aviso cancelado sai da caixa de entrada');
select pg_temp.actor('owner');
select is(pg_temp.ops('finance')->'summary'->>'receivable','2500','reserva permanece a receber e não é receita');
select is(pg_temp.ops('finance')->'summary'->>'refunds','4000','devoluções vêm das provas financeiras');
select pg_temp.actor('member');
select lives_ok($$select public.member_event_interest(pg_temp.fi('event2'),false,false)$$,'retirar interesse encerra preferência de e-mail');
reset role;
select is((select email_consent from private.event_interests where event_id=pg_temp.fi('event2') and user_id=pg_temp.fi('member')),false,'interesse retirado não mantém opt-in');
select is((select email_consent from private.event_contact_preferences where order_id=pg_temp.fi('free-order')),false,'pedidos sem autorização não ganham e-mail retroativo');
select finish();rollback;
